  "regulatory_constraints": [
    {
      "type": "Safety",
      "requirement": "If a large whale is sighted within 200 m of the forward path of a vessel, the vessel operator must reduce speed and shift the engine to neutral. Engines must not be engaged until the whale has moved outside of the vessel's path and beyond 500 m. If stationary, the vessel must not engage engines until the large whale has moved beyond 500 m.",
      "scope": "Vessels operating near large whales",
      "numerical_value": 200,
      "unit": "meters",
      "source": "Document section 5.8.7",
      "related_domains": ["Environmental", "Safety"]
    },
    {
      "type": "Safety",
      "requirement": "If a sea turtle or manta ray is sighted at any distance within the operating vessel's forward path, the vessel operator must slow down to 4 knots or less and steer away (unless unsafe to do so) until there is a separation distance of at least 100 m, at which time the vessel may resume normal operations. If a sea turtle is sighted within 50 m of the forward path of the operating vessel, the vessel operator must shift to neutral when safe to do so and then proceed away from the turtle at a speed of 4 knots when the sea turtle is no longer in the forward path of the vessel. The vessel may resume normal operations after it has passed 100 m from the turtle.",
      "scope": "Vessels operating near sea turtles and manta rays",
      "numerical_value": [50, 100],
      "unit": "meters",
      "source": "Document section 5.8.8",
      "related_domains": ["Environmental", "Safety"]
    },
    {
      "type": "Safety",
      "requirement": "Vessel operators must avoid transiting through areas of visible jellyfish aggregations or floating sargassum lines or mats. If operational safety prevents avoidance of such areas, vessels must slow to 4 knots while transiting through such areas.",
      "scope": "Vessels transiting through areas with jellyfish or sargassum",
      "numerical_value": 4,
      "unit": "knots",
      "source": "Document section 5.8.8.1",
      "related_domains": ["Environmental", "Safety"]
    },
    {
      "type": "Environmental",
      "requirement": "All vessel crew members must be briefed in the identification of sea turtle in regulations and best practices for avoiding vessel collisions. Reference materials must be available aboard all Project vessels for identification of sea turtles. The requirement and process for reporting of sea turtles (including live, entangled, and dead individuals) must be clearly communicated and posted in highly visible locations aboard all Project vessels, so that there is a clear requirement for reporting to the designated vessel contact (such as the lookout or the vessel captain), as well as a communication channel and process for crew members to do so.",
      "scope": "Vessel crew members and all Project vessels",
      "numerical_value": null,
      "unit": null,
      "source": "Document section 5.8.8.2",
      "related_domains": ["Environmental", "Safety"]
    }
